const rawText = item.json.content[0].text;

// Strip markdown code fences (```json ... ``` or ``` ... ```)
let cleaned = rawText
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```\s*$/i, '')
  .trim();

let contenido;

// Attempt 1: direct parse on cleaned text
try {
  contenido = JSON.parse(cleaned);
} catch (e1) {
  // Attempt 2: balanced-brace extraction (avoids greedy regex issues)
  let depth = 0, start = -1, end = -1;
  for (let i = 0; i < cleaned.length; i++) {
    if (cleaned[i] === '{') {
      if (depth === 0) start = i;
      depth++;
    } else if (cleaned[i] === '}') {
      depth--;
      if (depth === 0) { end = i; break; }
    }
  }
  if (start !== -1 && end !== -1) {
    try {
      contenido = JSON.parse(cleaned.slice(start, end + 1));
    } catch (e2) {
      contenido = { error: 'Parse fallido: ' + e2.message, raw: rawText.substring(0, 500) };
    }
  } else {
    contenido = { error: 'JSON no encontrado en respuesta', raw: rawText.substring(0, 500) };
  }
}

return {
  json: {
    contenido: contenido,
    fecha_generacion: new Date().toISOString()
  }
};

